from html import escape

STYLE="""body{margin:0;background:#faf9f7;color:#1c252c;font:16px system-ui,Arial}header{background:#152c39;color:white;padding:24px max(20px,calc((100% - 850px)/2))}header h1{margin:0;font-size:29px}header p{margin:8px 0 0;color:#dae6e9}main{max-width:850px;margin:32px auto;padding:0 18px}.panel{background:#fff;border:1px solid #e1e5e6;border-radius:13px;padding:25px;box-shadow:0 3px 10px #12232a0c}label{display:block;font-weight:600;margin:15px 0 5px}input[type=number]{box-sizing:border-box;width:100%;padding:11px;border:1px solid #aebbc3;border-radius:6px;font:inherit}.check{display:inline-flex;gap:5px;margin:5px 16px 5px 0;font-weight:400}button{margin-top:20px;border:0;background:#176d72;color:white;padding:13px 20px;border-radius:7px;font:inherit;cursor:pointer}.alert{padding:14px;background:#fff0ed;border:1px solid #e6a496;border-radius:7px}.result{margin-top:22px}.result li{margin:7px 0}.muted{font-size:13px;color:#5b6971}footer{max-width:850px;margin:20px auto;padding:12px 18px;font-size:13px;color:#657078}"""
def page(result=None,error=None):
    result_html=''
    if error: result_html=f'<p class="alert" role="alert">{escape(error)}</p>'
    if result:
        items=''.join(f'<li>Día {x["dia"]}: {escape(x["nombre"])} — S/ {x["costo"]:.2f} ({x["duracion"]} h)</li>' for x in result['lugares'])
        result_html=f'<section class="panel result"><h2>Itinerario #{result["id"]}</h2><ul>{items}</ul><p><b>Costo referencial:</b> S/ {result["costo"]:.2f} · <b>Saldo:</b> S/ {result["saldo"]:.2f}</p><p class="muted">Guardado en SQLite. Esta demostración no considera traslado ni disponibilidad real.</p></section>'
    return f"""<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ayacucho Conecta</title><style>{STYLE}</style></head><body><header><h1>Ayacucho Conecta</h1><p>Organiza tu visita a Ayacucho según tus intereses y presupuesto</p></header><main><section class="panel"><h2>Arma tu itinerario</h2><form method="post" action="/generar"><label for="dias">Días disponibles (1–14)</label><input required id="dias" name="dias" type="number" min="1" max="14" value="3"><label for="presupuesto">Presupuesto en soles</label><input required id="presupuesto" name="presupuesto" type="number" min="1" step="0.01" value="300"><label>¿Qué te interesa?</label><div>{''.join(f'<label class="check"><input type="checkbox" name="intereses" value="{x}" {"checked" if i==0 else ""}>{label}</label>' for i,(x,label) in enumerate([("cultura","Cultura e historia"),("naturaleza","Naturaleza"),("gastronomia","Gastronomía"),("aventura","Aventura")]))}</div><button type="submit">Generar itinerario</button></form><p class="muted">Los lugares, tarifas y duraciones son de demostración, no información turística verificada.</p></section>{result_html}</main><footer>PMV1 académico · Datos ficticios · No se realizan reservas ni pagos.</footer></body></html>"""
